SELECT s.name AS schema_name,t.name AS table_name,c.column_id,c.name AS column_name,ty.name AS sql_type,c.max_length,c.precision,c.scale,c.is_nullable,c.is_identity,c.is_computed,dc.name AS default_name,dc.definition AS default_definition,cc.definition AS computed_definition FROM sys.tables t JOIN sys.schemas s ON s.schema_id=t.schema_id JOIN sys.columns c ON c.object_id=t.object_id JOIN sys.types ty ON ty.user_type_id=c.user_type_id LEFT JOIN sys.default_constraints dc ON dc.object_id=c.default_object_id LEFT JOIN sys.computed_columns cc ON cc.object_id=c.object_id AND cc.column_id=c.column_id WHERE t.name LIKE 'ProductosServicios%' ORDER BY t.name,c.column_id